import{_ as e,o as i,c as t,a2 as s}from"./chunks/framework.CWdVbaJB.js";const u=JSON.parse('{"title":"Authentication","description":"","frontmatter":{"title":"Authentication"},"headers":[],"relativePath":"platform/authentication.md","filePath":"platform/authentication.md"}'),n={name:"platform/authentication.md"};function o(l,a,r,h,d,p){return i(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h1><p>SHAVIRA supports email/password authentication, Google OAuth, and API key authentication.</p><h2 id="email-password" tabindex="-1">Email &amp; Password <a class="header-anchor" href="#email-password" aria-label="Permalink to &quot;Email &amp; Password&quot;">​</a></h2><h3 id="sign-up" tabindex="-1">Sign Up <a class="header-anchor" href="#sign-up" aria-label="Permalink to &quot;Sign Up&quot;">​</a></h3><ol><li>Open SHAVIRA and click <strong>Sign up</strong></li><li>Enter your name, email, and password</li><li>Click <strong>Create account</strong></li></ol><p>Password requirements:</p><ul><li>Minimum 12 characters</li><li>At least one uppercase letter</li><li>At least one number</li><li>At least one special character</li></ul><p>If email verification is enabled, check your inbox for a verification link before signing in.</p><h3 id="sign-in" tabindex="-1">Sign In <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign In&quot;">​</a></h3><p>Enter your email and password and click <strong>Sign in</strong>. Sessions last 8 hours with automatic refresh for up to 30 days.</p><h3 id="rate-limiting" tabindex="-1">Rate Limiting <a class="header-anchor" href="#rate-limiting" aria-label="Permalink to &quot;Rate Limiting&quot;">​</a></h3><p>Five failed login attempts temporarily block further attempts from the same email or IP address.</p><h3 id="forgot-password" tabindex="-1">Forgot Password <a class="header-anchor" href="#forgot-password" aria-label="Permalink to &quot;Forgot Password&quot;">​</a></h3><ol><li>Click <strong>Forgot password</strong> on the login screen</li><li>Enter your email — a reset link is sent (valid for 1 hour)</li><li>Click the link and set a new password</li></ol><div class="tip custom-block"><p class="custom-block-title">Local Development</p><p>In <code>noop</code> email mode, the reset token is printed to the API log:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> security-ai-agent-api</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Password reset token&quot;</span></span></code></pre></div></div><h2 id="google-oauth" tabindex="-1">Google OAuth <a class="header-anchor" href="#google-oauth" aria-label="Permalink to &quot;Google OAuth&quot;">​</a></h2><p>Sign in with Google instead of a password.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p>The admin must configure these environment variables:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GOOGLE_CLIENT_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-client-id</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GOOGLE_CLIENT_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-client-secret</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GOOGLE_CALLBACK_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://localhost:4000/api/auth/google/callback</span></span></code></pre></div><p>When configured, a <strong>Continue with Google</strong> button appears on the login screen.</p><h3 id="first-time-google-login" tabindex="-1">First-Time Google Login <a class="header-anchor" href="#first-time-google-login" aria-label="Permalink to &quot;First-Time Google Login&quot;">​</a></h3><p>If no SHAVIRA account exists with your Google email, one is created automatically with your Google profile picture.</p><h3 id="linking-accounts" tabindex="-1">Linking Accounts <a class="header-anchor" href="#linking-accounts" aria-label="Permalink to &quot;Linking Accounts&quot;">​</a></h3><p>If a SHAVIRA account already exists with the same email, the Google login links to it — your existing workspace and data are preserved.</p><h2 id="session-management" tabindex="-1">Session Management <a class="header-anchor" href="#session-management" aria-label="Permalink to &quot;Session Management&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Token</th><th>Lifetime</th><th>Purpose</th></tr></thead><tbody><tr><td>Access token (<code>shv_token</code>)</td><td>8 hours</td><td>Authenticates API requests</td></tr><tr><td>Refresh token (<code>shv_refresh</code>)</td><td>30 days</td><td>Refreshes access tokens</td></tr></tbody></table><p>Both tokens are set as HTTP-only cookies. Signing out invalidates all tokens immediately.</p><h2 id="api-key-authentication" tabindex="-1">API Key Authentication <a class="header-anchor" href="#api-key-authentication" aria-label="Permalink to &quot;API Key Authentication&quot;">​</a></h2><p>For SDK and collector integrations, use API keys instead of session cookies. See <a href="/shavira-docs/platform/api-keys.html">API Keys</a>.</p>`,30)])])}const g=e(n,[["render",o]]);export{u as __pageData,g as default};
